using System;
using System.IO;
using System.Linq;
using Paco.Domain;
using Newtonsoft.Json.Linq;
public static class DomainTests {
    static int tests;
    static void Check(bool yes,string label){if(!yes)throw new Exception(label);}
    static void Test(string name,Action body){body();tests++;Console.WriteLine("PASS "+name);}
    static void Reject(Action action){bool failed=false;try{action();}catch{failed=true;}Check(failed,"Must reject");}
    public static void Main(string[] args){string root=args[0],data=Path.Combine(root,"Assets/Paco/Resources/Data");var cat=new Catalog(File.ReadAllText(Path.Combine(data,"stages.json")),File.ReadAllText(Path.Combine(data,"lessons.json")));int count=cat.Stages.Length;
        Test("30 configured stages and learning tasks",()=>Check(count==30&&cat.Lessons.Length==30,"Catalogue"));
        Test("All 30 stages solved within move budget for five seeds",()=>{foreach(var s in cat.Stages)foreach(int seed in new[]{1,47,101,4701,7919}){var e=new MatchEngine(s,seed);Check(MatchEngine.Matches(e.Board).Count==0,"Stable");Check(MatchEngine.Hint(e.Board)!=null,"Playable");int n=e.Moves;while(n-->0&&!e.Won){var h=MatchEngine.Hint(e.Board);Check(h!=null&&e.Swap(h[0],h[1]),"Legal");}Check(e.Won,"Reachable stage "+s.index);}});
        Test("Invalid exchange returns board without consuming a move",()=>{var e=new MatchEngine(cat.Stages[0]);var b=(int[])e.Board.Clone();for(int i=0;i<48;i++)if(MatchEngine.Adjacent(i,i+1)&&!e.Swap(i,i+1)){Check(e.Moves==24&&b.SequenceEqual(e.Board),"No penalty");Check(e.Frames.Last().Phase==Phase.Revert,"Revert animation");return;}throw new Exception("Fixture");});
        Test("Snapshots and gravity destinations remain consistent",()=>{var e=new MatchEngine(cat.Stages[0]);var h=MatchEngine.Hint(e.Board);e.Swap(h[0],h[1]);foreach(var f in e.Frames){Check(f.Before.Length==49&&f.After.Length==49,"Snapshot");if(f.Phase==Phase.Fall){Check(f.Motions.Length==49&&f.Motions.Select(x=>x.To).Distinct().Count()==49,"49 destinations");foreach(var m in f.Motions)Check(f.After[m.To]==m.Type,"Gravity type");}}});
        Test("Unique sequential rewards and full v4 roundtrip",()=>{Player p=new Player();Reject(()=>p.Win(2,count));for(int i=0;i<count;i++){p=p.Win(i,count).Learn(i,count);int cash=p.cash;p=p.Win(i,count);Check(p.cash==cash,"No replay farming");p=PlayerCodec.Decode(PlayerCodec.Encode(p,count),count);}Check(p.cash==55000&&p.Unlocked(count)==30,"Complete");Reject(()=>p.Win(30,count));});
        Test("Legacy v1 v2 v3 saves unlock stage seven without extra credit",()=>{Player p=new Player();for(int i=0;i<6;i++)p=p.Win(i,count).Learn(i,count);foreach(int v in new[]{1,2,3}){JObject j=JObject.Parse(PlayerCodec.Encode(p,count));j["version"]=v;var q=PlayerCodec.Decode(j.ToString(),count);Check(q.Unlocked(count)==6&&q.cash==19000,"Migration");}p=p.Win(6,count);var bad=JObject.Parse(PlayerCodec.Encode(p,count));bad["version"]=3;Reject(()=>PlayerCodec.Decode(bad.ToString(),count));});
        Test("Trades retain cards and charge fees",()=>{Player p=new Player().Win(0,count).Learn(0,count).Win(1,count).Learn(1,count);int cash=p.cash;p=p.Trade("cacao",true,count).Trade("cacao",false,count);Check(p.cash==cash-50&&p.companyCards.Contains("cacao"),"Fee/card");Reject(()=>p.Trade("cacao",false,count));});
        Test("All six lands and construction families use earned progress",()=>{Player p=new Player();Reject(()=>p.BuyLand("rive",count));for(int i=0;i<8;i++)p=p.Win(i,count).Learn(i,count);foreach(var l in EconomyCatalog.Lands){p=p.BuyLand(l.Id,count).Build(l.Id,"ferme",count);}Check(p.ownedPlots.Count==6&&p.townBuildings.Count==6,"Expansion");Reject(()=>p.Build("rive","banque",count));Reject(()=>p.BuyLand("rive",count));});
        Test("Dividend preserves total value at detachment",()=>{Player p=new Player();for(int i=0;i<5;i++)p=p.Win(i,count).Learn(i,count);p=p.Trade("cacao",true,count).Drop(count);long total=p.TotalValue();p=p.Dividend(count);Check(p.TotalValue()==total,"Total value");int cash=p.cash;p=p.Dividend(count);Check(p.cash==cash,"Unique dividend");});
        Test("Corrupt, duplicate, nonsequential and incorrectly typed saves rejected",()=>{var j=JObject.Parse(PlayerCodec.Encode(new Player(),count));j["completed"]=new JArray(0,0);Reject(()=>PlayerCodec.Decode(j.ToString(),count));j["completed"]=new JArray(2);Reject(()=>PlayerCodec.Decode(j.ToString(),count));j["completed"]=new JArray();j["cash"]=3.5;Reject(()=>PlayerCodec.Decode(j.ToString(),count));Reject(()=>PlayerCodec.Decode("{}",count));});
        Test("Deadline does not restart and includes background elapsed time",()=>{var c=new RoundClock(90);c.Start(100);c.Start(120);Check(c.Remaining(130)==60,"No restart");Check(c.Remaining(191)==0,"Expired");});
        Test("Atomic save and backup recover a corrupt latest file",()=>{string folder=Path.Combine(Path.GetTempPath(),"paco-unity-test-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{string path=Path.Combine(folder,"save.json");var store=new SaveStore(path,count);var p=store.Load();store.Save(p);store.Save(p.Win(0,count));Check(store.Load().cash==11500,"Persist");File.WriteAllText(path,"corrupt");Check(store.Load().cash==10000,"Backup recovery");}finally{Directory.Delete(folder,true);}});
        Test("45 journey rewards are sequential, unique and preserved",()=>{Player p=new Player();Reject(()=>JourneyRules.Answer(p,1,0,count));for(int c=0;c<15;c++)for(int q=0;q<3;q++){p=JourneyRules.Answer(p,c,q,count);int cash=p.cash;p=JourneyRules.Answer(p,c,q,count);Check(p.cash==cash,"Unique quiz reward");}p=PlayerCodec.Decode(PlayerCodec.Encode(p,count),count);Check(p.cash==23500&&p.journeyAnswers.Count==45,"Journey saved");});
        Console.WriteLine(tests+" domain tests passed; Unity runtime/rendering NOT exercised.");
    }
}
